INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backgammon Blitz', 'Backgammon''s back... with a bang! Beloved by millions, played for centuries, backgammon is a two-player strategy game quite unlike any other. The goal is simple: race to get your checkers off the board first, but the deceptively deep rules and rhythm of backgammon has secured it as a favorite among casual and veteran players alike.' FROM games WHERE igdb_id = 8660 ON CONFLICT (game_id, language_code) DO NOTHING;
