INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('riptide-gp2', 16735, '2013-07-25', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vgj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzz7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riptide GP2', 'Rev up your rocket-powered hydro jet and put your racing skills to the test as you rip across a dynamic, ever-changing torrent of waves in Riptide GP2. Race through futuristic cityscapes, twisting canals and rivers, open harbors and mysterious research facilities. Hurl yourself off sky-high jumps and bust out death defying stunts. Build a collection of powerful watercraft and customize their performance and paint schemes to suit your individual style. Take your skills online to battle other players around the world -- or trade elbows with friends in split-screen matches right in your home!' FROM games WHERE igdb_id = 16735 ON CONFLICT (game_id, language_code) DO NOTHING;
