INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zombie-solitaire', 9306, '2013-11-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaxde.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkfu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Solitaire', 'An infected tofu burger has transformed some poor soul into a brain-devouring zombie and you need to run for your life! Before you can get your sweet behind to salvation on a zombie-free island, you’ll need to puzzle your way though exciting rounds of solitaire and fun mini-games. But watch out! The hungry zombie horde is hot on your heels! Biting humor and fun card-game action await you in Zombie Solitaire. You’ll have to use your brain if you want to keep it!' FROM games WHERE igdb_id = 9306 ON CONFLICT (game_id, language_code) DO NOTHING;
