INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mind Zero', 'Mind Zero is an action-packed dungeon-crawler RPG. Play as Kei, a high school student whose life turns upside down when he forms a contract with a “MIND,” a weapon/being with deadly powers. With the government and other forces trailing him and his friends, Kei will need to discover the secret behind “MIND.” Will these newfound powers help him or ultimately be his doom?' FROM games WHERE igdb_id = 8283 ON CONFLICT (game_id, language_code) DO NOTHING;
