INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Puzzle Quest', 'Developed by Demiurge Studios, "Marvel Puzzle Quest: Dark Reign" features team-based gameplay for the first time ever in the Puzzle Quest franchise. Players will assemble a team of three characters with upgradable abilities, choosing from a roster of heroes and villains alike, all to combat a common enemy. With this team-based gameplay comes a new level of strategy and customization, allowing audiences to call upon specific heroes that are best suited for the job and to create an ultimate Marvel dream team' FROM games WHERE igdb_id = 7084 ON CONFLICT (game_id, language_code) DO NOTHING;
