INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Depression Quest', 'Depression Quest is an interactive fiction game where you play as someone living with depression. You are given a series of everyday life events and have to attempt to manage your illness, relationships, job, and possible treatment. This game aims to show other sufferers of depression that they are not alone in their feelings, and to illustrate to people who may not understand the illness the depths of what it can do to people.' FROM games WHERE igdb_id = 10238 ON CONFLICT (game_id, language_code) DO NOTHING;
