INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: The Ghost of Thornton Hall', 'Jessalyn Thornton’s fateful sleepover at the abandoned Thornton estate was supposed to be a pre-wedding celebration, but the fun ended when she disappeared. While her family searches for clues, others refuse to speak about the estate’s dark past. Did something supernatural happen to Jessalyn, or is someone in Thornton Hall holding something besides family secrets?' FROM games WHERE igdb_id = 16451 ON CONFLICT (game_id, language_code) DO NOTHING;
