INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TagPro', 'TagPro is a free-to-play online multiplayer capture the flag video game originally designed and programmed by Nick Riggs. The first version was released in February 2013, after Riggs began experimenting with software platform Node.js. The game is named after one of its three obtainable power-ups. It follows the basic rules of capture the flag, along with some modifications, including power-ups, spikes, and other map elements.' FROM games WHERE igdb_id = 9604 ON CONFLICT (game_id, language_code) DO NOTHING;
