INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bunny Must Die! Chelsea and the 7 Devils', 'From the creator of the Gundemonium Collection comes a thrilling new 2D action-platformer! Help Bunny escape the Devils’ Labyrinth and defeat the 7 Devils in this hilariously over-the-top action-platformer game. Battle through a large, connected map filled with unique enemies, traps, and puzzles. Use magical items like the Sylph Shooter and the Hyper Heels to power up and defeat the 7 Devils. Manipulate the fabric of time to solve puzzles and survive. Will Bunny be rid of those new ears she so despises? Only with your assistance can she brave this dangerous maze...' FROM games WHERE igdb_id = 16661 ON CONFLICT (game_id, language_code) DO NOTHING;
