INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tiger-woods-pga-tour-14', 5227, '2013-03-26', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22tp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u5zbggmolh9wka8olhg0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 14', 'The world''s number one selling golf video game franchise returns with an array of exciting new features. Go back in time and step onto the course with Arnold Palmer, Jack Nicklaus, Gary Player, and other legends in their prime. Overtake each star on the biggest stages in the world of golf using equipment and wearing clothing from that era. Eclipse their legacies and cement your seat at the table of legends. Then play golf at night, with illuminated golf balls, or join up with friends and form the ultimate "twenty-foursome" for the most authentic golf experience ever with Tiger Woods PGA TOUR 14.' FROM games WHERE igdb_id = 5227 ON CONFLICT (game_id, language_code) DO NOTHING;
