INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R.I.P.D.: The Game', 'Based on the 3D supernatural action-adventure film, R.I.P.D., you and a partner will take up the holsters of two lawmen dispatched to the otherworld to protect and serve the living from an increasingly destructive array of souls who refuse to move peacefully to the other side. Top-notch teamwork and an arsenal of badass weapons are the keys to defeating your enemies and bringing order back to the world.' FROM games WHERE igdb_id = 16525 ON CONFLICT (game_id, language_code) DO NOTHING;
