INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flappy Bird', 'Flappy Bird is a 2013 mobile game developed by Vietnamese artist and programmer Dong Nguyen, under his game development company dotGEARS. The game is a side-scroller where players control a bird trying to fly between columns of green pipes without hitting them. Your score in the game depends on how many pipes you successfully pass.' FROM games WHERE igdb_id = 7671 ON CONFLICT (game_id, language_code) DO NOTHING;
