INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frozen: Olaf''s Quest', 'In this humorous epilogue to the motion picture, ‘Disney Frozen: Olaf’s Quest’ hands center spotlight to Olaf, the outgoing, innocent and comically carefree snowman from Disney’s epic comedy adventure. It pairs tightly tuned platforming action with light puzzle-solving elements across 60 imaginative levels, complete with hidden collectibles, side challenges and unlockable customization items.' FROM games WHERE igdb_id = 85088 ON CONFLICT (game_id, language_code) DO NOTHING;
