INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet & Clank: Into the Nexus', 'Ratchet & Clank: Into the Nexus (known as Ratchet & Clank: Nexus in Europe) is a 2013 platform video game developed by Insomniac Games and published by Sony Computer Entertainment for the PlayStation 3. It is the fourth and final installment in the "Future" series. The series is noted for the inclusion of exotic and unique locations and over the top gadgets, a concept of the traditional Ratchet & Clank experience, that returns in this game.' FROM games WHERE igdb_id = 2589 ON CONFLICT (game_id, language_code) DO NOTHING;
