INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Legends of Chima: Laval''s Journey', 'Get ready for an epic adventure as Laval races to unlock the secret of the legendary triple-Chi armour before Cragger can manipulate its awesome power to threaten the balance of Chima itself! Laval and his allies will explore Lion Temple, Eagle Spire, Gorilla Forrest, Rhino Quary, Croc Swamp and more as they harness the power of Chi to leap, swing, fly and fight through 15 levels of intense action! Can Laval discover the truth behind the legend of the triple-Chi before it’s too late?' FROM games WHERE igdb_id = 6839 ON CONFLICT (game_id, language_code) DO NOTHING;
