INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pandemic: The Board Game', 'A digital translation of the popular board game. As skilled members of a disease-fighting team, you must keep four deadly diseases at bay while discovering their cures. Travel the world, treat infections, and find cures. You must work as a team to succeed. The clock is ticking as outbreaks and epidemics fuel the spreading plagues. Can you find all four cures in time? The fate of humanity is in your hands.' FROM games WHERE igdb_id = 69425 ON CONFLICT (game_id, language_code) DO NOTHING;
