INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impire', 'In Impire, you take control the of demon Báal-Abaddon as he attempts to rebuild his mighty hell spawn form. With the aid of dozens of evil creatures big and small as well as an arsenal of spells, you will help him construct a dungeon underworld of limitless evil and nastiness to stop all those pesky Heroes of Ardania from ruining his return to greatness!' FROM games WHERE igdb_id = 2916 ON CONFLICT (game_id, language_code) DO NOTHING;
