INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us', 'The Last of Us is a third-person action-adventure game featuring a mix of exploration, stealth and combat. Players face both infected creatures and hostile human enemies while progressing through varied environments. The game includes a narrative-driven single-player campaign and a competitive online multiplayer mode called Factions. Trophy support is included, and additional downloadable content was made available separately.' FROM games WHERE igdb_id = 1009 ON CONFLICT (game_id, language_code) DO NOTHING;
