INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Yawhg', 'The Yawhg is a one-to-four-player choose-your-own-adventure game that randomizes a unique story every time you play. The evil Yawhg is returning. How will the town''s locals lead their lives in the meanwhile, and what will they do when the dreaded Yawhg finally arrives? The fate of a community hinges on the characters'' actions, and the decisions of their players.' FROM games WHERE igdb_id = 3031 ON CONFLICT (game_id, language_code) DO NOTHING;
