INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adventure-time-explore-the-dungeon-because-i-don-t-know', 4557, '2013-11-15', 42, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ezg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ici.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Time: Explore the Dungeon Because I Don''t Know!', 'Princess Bubblegum summons Finn and Jake to the Candy Kingdom to investigate a rash of thefts and kidnappings that have plagued her kingdom. She thinks the cause lies within her Secret Royal Dungeon, where only the nastiest monsters and criminals are locked up. If they’ve found a way to escape, the Land of Ooo will be in danger! Following the mathematical, algebraic, and radical success of 2012’s Adventure Time: Hey Ice King! Why’d You Steal Our Garbage?!!, show creator Pendleton Ward teams up with developer WayForward in the all-new action game Adventure Time: Explore the Dungeon Because I DON’T KNOW!, and team up with your friends in four-player co-operative multiplayer as the Adventure Time world comes to life through beautiful pixel animations, and voiceover from the original cast.' FROM games WHERE igdb_id = 4557 ON CONFLICT (game_id, language_code) DO NOTHING;
