INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Donnie Saves a Princess', 'Teenage Mutant Ninja Turtles: Donnie Saves A Princess is a Flash-based browser game released on the Nickelodeon website in April of 2013. Donatello falls asleep while playing video games, and dreams that he goes through several TMNT-ized classic games to rescue "princess" April. At the end of each level, he encounters one of his brothers, dressed up like the princess that fits that level''s theme. After he rescues each, they say, "The princess you are looking for is in/on another dungeon/castle/space ship."' FROM games WHERE igdb_id = 63459 ON CONFLICT (game_id, language_code) DO NOTHING;
