INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Walk in the Dark', 'In this action platformer you play as a cat, Bast, running through a dark fantasy world. You’ll be running, jumping and sliding with smooth and precise controls designed to make you feel like a cat. But it wont be easy. In the dark you never know what lies in the shadows. In this dark journey you will face strange creatures and dangerous traps.' FROM games WHERE igdb_id = 16646 ON CONFLICT (game_id, language_code) DO NOTHING;
