INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color Zen', 'Color Zen is a new kind of puzzle game. With simple, intuitive controls, the game invites you to relax and immerse yourself. There are no points or penalties for failure; just an abstract world of color to move through at your own pace. So put on your headphones and find your way, with Color Zen.' FROM games WHERE igdb_id = 39209 ON CONFLICT (game_id, language_code) DO NOTHING;
