INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Theft Auto V', 'Grand Theft Auto V is a vast open world game set in Los Santos, a sprawling sun-soaked metropolis struggling to stay afloat in an era of economic uncertainty and cheap reality TV. The game blends storytelling and gameplay in new ways as players repeatedly jump in and out of the lives of the game’s three lead characters, playing all sides of the game’s interwoven story.' FROM games WHERE igdb_id = 1020 ON CONFLICT (game_id, language_code) DO NOTHING;
