INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Warrior', 'Shadow Warrior is a bold reimagining of the 3D Realms'' cult classic shooter from independent developer Flying Wild Hog (Hard Reset) starring the legendary and quick-witted warrior Lo Wang. Combine the brute force of overwhelming firepower with the elegant precision of a katana to annihilate the merciless armies of the shadow realm in an exhilarating and visually stunning transformation of the classic first-person shooter.' FROM games WHERE igdb_id = 6057 ON CONFLICT (game_id, language_code) DO NOTHING;
