INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superfrog HD', 'Superfrog HD is a remaster of the original Superfrog, released in 1993. The game has new, enhanced high definition cartoon style artwork, 24 new levels (including bosses) from six different worlds, and an endless runner mode called Frog Trials. The levels have been tweaked, but it is possible to unlock the original level layouts.' FROM games WHERE igdb_id = 8873 ON CONFLICT (game_id, language_code) DO NOTHING;
