INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cave', 'SEGA of America Inc. and Double Fine Productions have joined forces with legendary game designer, Ron Gilbert, to create The Cave. In this 2D puzzle action and adventure game, players will assemble a team of three from seven unlikely adventurers, each with their own unique personalities and stories. From there, you will descend into the mysterious depths to explore locations including a subterranean amusement park and a medieval castle, not to mention a fully armed and ready-to-launch nuclear tipped ICBM. The Cave awaits.' FROM games WHERE igdb_id = 2175 ON CONFLICT (game_id, language_code) DO NOTHING;
