INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('broken-sword-5-the-serpents-curse', 2924, '2013-12-04', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mn5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9lt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Sword 5: The Serpent''s Curse', 'Broken Sword 5: The Serpent''s Curse is a classical point & click adventure. It abandons 3D graphics and direct control which were used in the two predecessors and returns to the style of the first two games. The only major technical differences are a higher resolution and that the characters are modelled instead of drawn. The game uses an intelligent mouse cursor: a right click on a hotspot results in looking at the item and a left click triggers an item-specific action. Of course this is the main ingredient of the puzzles: collecting items and using them on other items in order to solve problems. On some occasions there are also logic puzzles from a zoomed-in view on an object, e.g. connecting cables of an engine in order to repair the car''s horn. Another important part of the game are conversations with the various characters, some of them known from previous instalments. During the course of the game the controlled character switches between George and Nico. A help function supports players who are stuck.' FROM games WHERE igdb_id = 2924 ON CONFLICT (game_id, language_code) DO NOTHING;
