INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dynasty-warriors-gundam-reborn', 21072, '2013-12-19', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ky3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/btg51amfkvcpoyj6aruj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors: Gundam Reborn', 'Experience the thrill of piloting Mobile Suits through famous scenes spanning multiple Gundam anime series in the action-packed thrill ride Dynasty Warriors: Gundam Reborn. Relive the exciting battles and animation sequences with the largest roster of Mobile Suits seen and the largest number of missions ever spanning the entire Gundam series including Mobile Suit Gundam SEED in Official Mode. Fans can also select Mobile Suit pilots to operate any unlocked Mobile Suit in the game for crossover missions in Ultimate Mode. Gundam Reborn will also allow players to control massive Mobile Armor units for the first time in the series. Mobile Armor units tower over the opposition and deliver absolute destruction to the enemy with the Mobile Armor’s unique weapons.' FROM games WHERE igdb_id = 21072 ON CONFLICT (game_id, language_code) DO NOTHING;
