INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa Louie 2: When Burgers Attack!', 'Papa Louie 2: When Burgers Attack! This is the long awaited sequel to the hit game Papa Louie: When Pizzas Attack! Marty and Rita''s routine work day at the Burgeria turns into a nightmare when a strange portal appears in Papa''s Burgeria. Radley Madish, Sarge, and a legion of Burgerzillas terrorize the Burgeria and kidnap Papa Louie and all the loyal customers. It''s up to Marty and Rita to rescue the customers and find their favorite boss, Papa Louie.' FROM games WHERE igdb_id = 56402 ON CONFLICT (game_id, language_code) DO NOTHING;
