INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not the Robots', 'You are a robot in an office building. You have to eat furniture and not get caught. A mysterious story unfolds. Not The Robots is this year’s most exciting Roguelike Stealth Furniture Eating Simulator. It’s a game with random levels, permadeath, and the goal of eating furniture - which is also your stealth cover.' FROM games WHERE igdb_id = 16723 ON CONFLICT (game_id, language_code) DO NOTHING;
