INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alex Hunter: Lord of the Mind', 'Over many years, Private investigator Alex Hunter had worked on dozens of cases involving murder, theft, bribery and fraud; and nothing fazed him. Until, a young lady came to his house asking him to help find her father, the renowned scientist, Professor Patterson. The professor had vanished from his house, without a trace, over a month ago. Take on the role of Alex Hunter and investigate this mysterious disappearance.' FROM games WHERE igdb_id = 30374 ON CONFLICT (game_id, language_code) DO NOTHING;
