INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ride ''em Low', 'Enter the world of night racing and lowrider competitions. Buy your ride and keep it in a good condition to compete with other pretenders. Earn respect to race with better drivers and advance in the underground community to ultimately become the next racing king of the neighborhood.' FROM games WHERE igdb_id = 16205 ON CONFLICT (game_id, language_code) DO NOTHING;
