INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gun Godz', 'Gun Godz is a first person shooter about gun, gangster rap and the rich culture of Venus. Players try to escape the jail of a hotel, which is the only building on Venus and is owned by a record-label owner who happens to be the God of Guns. Featuring a fully Venusian soundtrack by Jukio ''KOZILEK'' Kallio and a single English track with rap lyrics by Adam ''Doseone'' Kidd.' FROM games WHERE igdb_id = 31439 ON CONFLICT (game_id, language_code) DO NOTHING;
