INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sniper: Ghost Warrior 2', 'Sniper: Ghost Warrior 2 is the only multi-platform, first-person, modern shooter exclusively designed around the sniper experience. It takes the bulls-eye precision of its predecessor to new and exciting heights, offering more diverse sniper challenges; a rebuilt AI system and the thrilling “one shot, one kill” precision that made the original a huge hit, selling 3 million copies worldwide. Taking advantage of the advanced capabilities of the CryENGINE3, Sniper: Ghost Warrior 2 also delivers striking graphic environments.' FROM games WHERE igdb_id = 1368 ON CONFLICT (game_id, language_code) DO NOTHING;
