INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts χ[chi]', 'Kingdom Hearts χ, stylized as Kingdom Hearts χ[chi], is a Kingdom Hearts game that is exclusive to PC browsers as the eighth game of the series. The game itself is free to play, but there are items available within it that can be purchased. Set before the events of the Keyblade War, Kingdom Hearts χ has simple, 2D graphics and allows all players to become Keyblade wielders.' FROM games WHERE igdb_id = 20287 ON CONFLICT (game_id, language_code) DO NOTHING;
