INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Adventure', 'The story retells the story of the 1999 anime series, in which seven children; Tai (Taichi), Matt (Yamato), Sora, Izzy (Koushiro), Mimi, Joe and T.K. (Takeru), are mysteriously transported to the Digital World, where they meet monster companions known as Digimon. Using the power of the Digivice to evolve their Digimon partners into more powerful forms, Tai, his friends and their Digimon companions must work together in order to save both the Digital World and their own. The game also features the story of the film, Our War Game!, as well as original scenarios exclusive to this game.' FROM games WHERE igdb_id = 64699 ON CONFLICT (game_id, language_code) DO NOTHING;
