INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boson X', 'Boson X is a physics-themed runner game where players navigate through a rotating particle accelerator environment. Players quantum leap between platforms in a subatomic realm, timing their jumps precisely while maintaining momentum to discover the elusive Boson X particle. The game features an abstract design that removes traditional floor and ceiling boundaries, creating a unique spatial perspective.' FROM games WHERE igdb_id = 7730 ON CONFLICT (game_id, language_code) DO NOTHING;
