INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Mutant Escape: Hulk Edition', 'During the experimental detonation of a gamma bomb, scientist Bruce Banner rushes to save teenager Rick Jones who has driven onto the testing field; Banner pushes Jones into a trench to save him, but is himself hit with the blast, absorbing massive amounts of gamma radiation. He awakens later in an infirmary, seeming relatively unscathed, but that night transforms into a lumbering gray form that breaks through the wall and escapes.' FROM games WHERE igdb_id = 187070 ON CONFLICT (game_id, language_code) DO NOTHING;
