INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avadon 2: The Corruption', 'Avadon 2: The Corruption is an epic fantasy role-playing adventure in an enormous and unique world. You can choose from five different character classes, each with dozens of unique spells and abilities. Explore cunning dungeons, hunt for hundreds of magical artifacts, and travel through an enormous world, full of secrets. Avadon 2 features many different endings. Save your people, or betray them. The choice is yours!' FROM games WHERE igdb_id = 10036 ON CONFLICT (game_id, language_code) DO NOTHING;
