INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Puzzle Platformer Deluxe', 'The title says it all. Take one part falling block puzzle game, combine one part old-school platformer, add a couple thousand pixels, blend and serve. Why match colored blocks when you can just shoot the hell out of them? Your goal is to survive as long as you can in the single player, or the competitive multiplayer, or many challenges to help build your skills.' FROM games WHERE igdb_id = 20997 ON CONFLICT (game_id, language_code) DO NOTHING;
