INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Juarez: Gunslinger', 'From the dust of a gold mine to the dirt of a saloon, Call of Juarez: Gunslinger is a real homage to the Wild West tales. Live the epic and violent journey of a ruthless bounty hunter on the trail of the West’s most notorious outlaws. Blurring the lines between man and myth, this adventure made of memorable encounters unveils the untold truth behind some of the greatest legends of the Old West.' FROM games WHERE igdb_id = 1976 ON CONFLICT (game_id, language_code) DO NOTHING;
