INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wii-fit-u', 5325, '2013-11-01', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p9r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kdl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wii Fit U', 'Wii Fit U is a new installment in the Wii Fit series, a brand that has sold more than 40 million units worldwide. The game combines fun and fitness with new exercises and activities, and incorporates the GamePad in unique ways. It''s compatible with the existing Wii Balance Board, and Wii Fit and Wii Fit Plus owners can transfer their existing workout data. Nintendo also revealed the Fit Meter, an advanced activity monitor that will be packaged with the game and enables users to track fitness activities throughout the day and upload that data back into Wii Fit U.' FROM games WHERE igdb_id = 5325 ON CONFLICT (game_id, language_code) DO NOTHING;
