INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zumba Fitness World Party', 'Take your work out to Brazil, Hawaii and beyond in this vibrant fitness journey packed with exotic rhythms and rich culture from around the world. Expand your horizons with 40+ high-energy routines, over 30 calorie-burning dance styles, and a red hot soundtrack featuring Lady Gaga, Pitbull, Daddy Yankee and more. Work your body as you set fitness goals, earn motivating rewards and dance with friends alongside your favorite celebrity Zumba instructors in the new World Tour mode. Transform your at home work out into a rockin'' global fitness-party with Zumba Fitness World Party!' FROM games WHERE igdb_id = 5308 ON CONFLICT (game_id, language_code) DO NOTHING;
