INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Narco Terror', 'Dishing out justice, one grenade at a time! Narco Terror combines the good of the old and the amazing of the new in an action-packed twin-stick shooter about an over-the-top one-man war against a drug cartel. In true arcade-style, it is filled with unlimited ammo, ear-splitting grenades, huge explosions, massive tanks, armed helicopters and fast planes. 1-2 players drop in/out, local and online.' FROM games WHERE igdb_id = 16446 ON CONFLICT (game_id, language_code) DO NOTHING;
