INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('urban-trial-freestyle', 9435, '2013-02-19', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pbz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrgh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Trial Freestyle', 'After reaching pole position in PlayStation Store Chart, the critically acclaimed Urban Trial Freestyle is now revving up for PC. The city is your playground! Nothing will stop you on your freestyle trials bike. Use the urban landscape to pull spectacular tricks - backflips, 360s, wallrides, ollies, and more. Customize your bike to boost your performance in Time Attack or Stunt mode. Choose between speed and style, developing your own unique riding style. Challenge the best riders in Ghost Mode. The variety and elaborate design of the different backdrops will keep you coming back for hours on end, to achieve a perfect run and knock the top riders off the leaderboard.
