INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lego-city-undercover-the-chase-begins', 6837, '2013-04-20', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fua.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1klx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO City Undercover: The Chase Begins', 'LEGO City Undercover: The Chase Begins. A prequel to the Wii U game, follow the exploits of Chase McCain as a rookie cop. Find out how the story of Chase McCain begins. Chase McCain is on his first assignment as a police offer-and it''s up to you to help him clean up LEGO City! By changing into different disguises, Chase has access to unique abilities, such as putting out fires as a Fireman and breaking open doors as a Robber. After using his skills to infiltrate criminal organizations, help Chase finish the job by slapping cuffs on the bad guys. With multiple areas of LEGO City to explore and a boatload of LEGO Bricks and Studs to collect, the chase has most certainly begun.' FROM games WHERE igdb_id = 6837 ON CONFLICT (game_id, language_code) DO NOTHING;
