INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strike Suit Zero', 'Strike Suit Zero is an action-packed arcade space shooter set in the final hours of a future Earth. The clock is ticking; your planet is about to be destroyed and its only hope is the Strike Suit -- an advanced, transforming spacecraft that empowers you with ludicrous firepower and awesome abilities. Every second is precious; you''ll be forced to fight with fury, choose targets on instinct and make snap decisions that will not only affect the outcome of your mission but your path through the game and the ultimate destiny of seven billion lives.' FROM games WHERE igdb_id = 8507 ON CONFLICT (game_id, language_code) DO NOTHING;
