INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('viscera-cleanup-detail-shadow-warrior', 16718, '2013-10-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ig3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arose.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viscera Cleanup Detail: Shadow Warrior', 'After the battle is over, someone has to cleanup the mess! Introducing Viscera Cleanup Detail: Shadow Warrior from RuneStorm, a unique crossover mini-game that combines the worlds of Viscera Cleanup Detail and Shadow Warrior. Step into the rubber soled shoes of the hapless janitor tasked with cleaning up Lo Wang''s mess after a devastating katana battle in the collector''s temple from Shadow Warrior. Mop up pools of blood, dispose of body parts, and get the collector''s gallery of antiques in tip top shape as quick as possible! Successfully clean the entire temple and collect all the scattered cash to unlock two Steam achievements!' FROM games WHERE igdb_id = 16718 ON CONFLICT (game_id, language_code) DO NOTHING;
