INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('takedown-red-sabre', 2937, '2013-09-20', 36, 'https://images.igdb.com/igdb/image/upload/t_cover_big/z8eobf5ehhm7dwwx5nqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cpzmeo3o6j5rjikoodl1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Takedown: Red Sabre', 'TAKEDOWN is a thinking-person’s shooter. The player that takes things slow, aims carefully, and plans their moves right will overcome the player who runs in with guns blazing. Close-quarters battle brings the fight inside, as you would see SWAT teams or SOF units taking down small numbers of dangerous adversaries. Non-linear environments allow for multiple routes and tactics and add replayability. The operation to clear pirates from a hijacked oil tanker by Russian special forces in May of 2010 is a perfect example of the types of missions in TAKEDOWN.' FROM games WHERE igdb_id = 2937 ON CONFLICT (game_id, language_code) DO NOTHING;
