INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of Loot', 'Heroes of Loot combines the action of twin-stick shooters with the dungeon crawling of rogue-likes. You''ll find yourself in the middle of hordes of ghosts, skulls, cyclops, critters and much more… Survive using quick reflexes, level up to improve your weapon, and if you have time complete some quests for extra loot and upgrades.' FROM games WHERE igdb_id = 13624 ON CONFLICT (game_id, language_code) DO NOTHING;
