INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marlow Briggs and the Mask of Death', 'Marlow Briggs and the Mask of Death is a third person action hack and slasher that is perfect for the player who wants to experience a game that brings to life the best of blockbuster films, over the top action and cinematic gameplay and comic book heroes, with its focus on relentless high-octane combat, exotic danger filled environments and epic set pieces.' FROM games WHERE igdb_id = 8006 ON CONFLICT (game_id, language_code) DO NOTHING;
