INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Arthur''s Gold', 'If you like total freedom in the way you conquer the enemy this is the ultimate war game for you. Build freeform constructions as a medieval Builder, fight in sword duels as a Knight or snipe with your bow as an Archer. King Arthur''s Gold blends the cooperative aspects of Lost Vikings, mashes them with the full destructibility of Worms and the visual style and action of Metal Slug, brought to you by the creators of Soldat.' FROM games WHERE igdb_id = 7209 ON CONFLICT (game_id, language_code) DO NOTHING;
