INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teslagrad', 'Teslagrad is a 2D puzzle platformer developed by Rain Games. Released in 2013, it is set in a steampunk-inspired world and revolves around the use of magnetism and electricity to solve puzzles. Players control a young boy who must navigate through a mysterious tower, using magnetic powers to manipulate the environment and overcome obstacles. The game is characterised by its lack of dialogue, relying on visual storytelling and atmospheric design to convey its narrative.' FROM games WHERE igdb_id = 7641 ON CONFLICT (game_id, language_code) DO NOTHING;
