INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teleglitch: Die More Edition', 'Teleglitch: Die More Edition is a roguelike top-down shooter with retro pixel graphics. Featuring procedurally generated maps that change with each play through, you will never experience the same facility twice. Clutch your gun, walk down the dark corridors and enter each new room hoping those last few rounds of ammunition will be enough. Feel the anxiety, the paranoia and the sheer terror of Teleglitch.' FROM games WHERE igdb_id = 7884 ON CONFLICT (game_id, language_code) DO NOTHING;
