INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Constant C', 'Constant C is a 2D puzzle platformer with two core gameplay mechanics - Gravity Shifting and the Time Field. Using these two mechanics in the game, the player controls the momentum of various objects to complete each level. Dive into the world of Constant C, where rules of fundamental physics no longer apply. In a space station far away from Earth, mysterious events have triggered the distortion of time. Journey through the game as a lone robot, who uncovers the truth behind the incident step by step, and finds the purpose of his own creation.' FROM games WHERE igdb_id = 16670 ON CONFLICT (game_id, language_code) DO NOTHING;
