INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9.03m', '9.03m, is a short, first person, art/empathy game for PC. Not a game in the traditional sense of the word; it aims to humanise, and remember the victims of the 2011 Japanese tsunami. The media is quick to put figures to death tolls in such disasters, and 9.03m tries to remind people of the individuals behind those figures.' FROM games WHERE igdb_id = 16837 ON CONFLICT (game_id, language_code) DO NOTHING;
