INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sacred Citadel', 'The once peaceful land of Ancaria is in grave danger. The evil Ashen empire has enslaved its population and is using the orc-like Grimmoc to wipe out the Seraphim, who swore to protect it. In order to defeat the empire you will have to prove yourself as a warrior by riding terrifying mounts, acquiring earth shattering skills and looting powerful weapons and valuable treasures. Grab your friends and join the resistance!' FROM games WHERE igdb_id = 15290 ON CONFLICT (game_id, language_code) DO NOTHING;
