INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talisman: Prologue', 'Talisman Prologue is an adaptation of the classic fantasy board game Talisman by Games Workshop. This version focuses on single player experience. An epic tale of dice rolling and card drawing takes you on a quest throughout the land to rescue Princesses, slay Dragons and recover lost artefacts. Play through over 50 quests using the Talisman board game rules, and learn the special abilities of all of the characters.' FROM games WHERE igdb_id = 10953 ON CONFLICT (game_id, language_code) DO NOTHING;
