INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take on Mars', 'Explore the rocky terrain and sandy wastes of Mars in this brand new installment to the Take On series. Developed by the creators of the award-winning Arma series and DayZ, Take On Mars places you right in the middle of mankind''s most exciting undertaking. Start out in the seat of a rover operator, pushing your vehicles to the max. Finish as the first human to have ever set foot on Mars. With a scientific arsenal at your disposal, you will pioneer the exploration of another planet, unlocking the secrets of Mars’ distant past.' FROM games WHERE igdb_id = 16572 ON CONFLICT (game_id, language_code) DO NOTHING;
