INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Action Mega Fight!', 'Big Action Mega Fight! is a classic single player beat ''em up/brawler with a modern twist! Hilarious 2D cartoon combat inspired by Streets of Rage, Final Fight, Turtles in Time and Battletoads. Blast your way through levels filled with luscious art and unforgettable enemies. How fast can you SMASH?' FROM games WHERE igdb_id = 35586 ON CONFLICT (game_id, language_code) DO NOTHING;
