INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('agricultural-simulator-historical-farming', 9954, '2013-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3l7i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arktr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agricultural Simulator: Historical Farming', 'Enjoy being a farmer between 1950 and 1970 in the Agricultural Simulator – Historical Farming. The game takes you to the good old days and you will experience the charming farming of the 60''s and 70''s. Fans of nostalgia and history will be glad to work with original designed machines and to till a field with well known Old-timer Tractors. With the new feature – the dynamic ground Agrar Simulator – Historical Farming presents the first real furrows which will be left when working at the fields with strong machines. The furrows will have impact on the driving behavior of the tractors and guarantee pure realism. It is up to the player to decide in which region he would like to cultivate his farm. There are two amazing scenarios – idyllic highlands, valleys and woods in the alp-region or the fascinating Toscana region with measured climate.' FROM games WHERE igdb_id = 9954 ON CONFLICT (game_id, language_code) DO NOTHING;
