INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fearful Tales: Hansel and Gretel - Collector''s Edition', 'You awake from a strange dream to find gingerbread men trashing your home. Where are your children? They left for the village store hours ago and have not returned. A mysterious woman appears, taunting you. Is she responsible for your children’s disappearance? One gingerbread man has promised to help you, but can you really trust him?' FROM games WHERE igdb_id = 22078 ON CONFLICT (game_id, language_code) DO NOTHING;
