INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rain', 'rain is the enchanting tale of a boy who chases after a girl with an invisible silhouette. After discovering that the girl is being hunted by ghostly creatures, he embarks on his own journey into the mysterious world of rain to save her. Upon entering the world he discovers that he has also become invisible and he must learn to navigate through the unknown, using the rain to guide and protect him.' FROM games WHERE igdb_id = 2969 ON CONFLICT (game_id, language_code) DO NOTHING;
