INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Fairy Pony - Dress Up Game For Girls', 'Welcome to Fairy Pony Forest, where you get to dress up and interact with your cute pony friends! As you explore the forest, keep an eye out for treasure chests. They contain new dress up items and treats for your ponies. While "My Fairy Pony" was specifically designed with small children in mind, everyone can enjoy exploring the magical beauty found throughout Fairy Pony Forest. Be the stylist that every pony dreams of! 
