INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Hunter', 'Welcome, bold adventurer! Card Hunter is an online collectible card game which blends together card play, deck building, tactical combat and fantasy role-playing in a way you''ve never seen before. Grab your cards, miniatures, dice and snacks, then journey to a new world of adventure on the tabletop of your Game Master, Gary.' FROM games WHERE igdb_id = 17231 ON CONFLICT (game_id, language_code) DO NOTHING;
