INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: World''s Best Driver', 'Gear up for intense challenges only Hot Wheels can deliver! Join the ranks of Team Hot Wheels, an elite group of drivers competing for the coveted title: “World’s Best Driver.” The drivers are split into four teams, each with their own disciplines: Super Fast (Green), Outrageous (Red), High-Tech (Blue) and Powerful (Yellow). Compete in thrilling events across four Hot Wheels Test Facility (HWTF) locations around the world. For the first time, Hot Wheels fans can experience the legendary world of HWTF where the latest and greatest Hot Wheels creations are born. Pick your team, choose your ride and GO FOR IT!' FROM games WHERE igdb_id = 10418 ON CONFLICT (game_id, language_code) DO NOTHING;
