INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-s-crown', 3002, '2013-07-25', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ncjwj2ityc3smuhyzcgu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Crown', 'Dragon''s Crown is a multiplayer hack-and-slash beat''em up game with breathtaking visual style, a design built around cooperative play, epic boss fights, and the ability to discover a new adventure in every play session. Developer Vanillaware deftly marries stunning hand-drawn and animated art work with deep, action-packed hardcore gameplay. Dragon''s Crown allows up to four players to team up locally or online to clear out monster-ridden dungeons, discover precious treasure, and destroy awe-inspiring bosses. Its unique, highly replayable design means that every time players can boot up and log on, they can expect a different experience. Unparalleled in their unique style, Vanillaware painstakingly hand-paints every detail, be it a blade of grass or the scales on the game''s impressive dragons. The game becomes a lush, vibrant storybook come to life when everything starts to animate in gorgeous full HD.' FROM games WHERE igdb_id = 3002 ON CONFLICT (game_id, language_code) DO NOTHING;
