INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wadanohara and the Great Blue Sea', 'Wadanohara and the Great Blue Sea is an adventure RPG made in late 2013. It follows the young witch Wadanohara and her familiars. After a journey from the witch world she had been visiting, she returns to her deep sea home to find it had been attacked by an unknown enemy. Wadanohara is tasked with repairing the magical barriers protecting the kingdom destroyed by this enemy, but fixing them shall not be the last of her worries...' FROM games WHERE igdb_id = 46614 ON CONFLICT (game_id, language_code) DO NOTHING;
