INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jones on Fire', 'Jones on Fire - a high-speed action game of kitty saving and flame evading, running and jumping, where YOU are the hero! Become Emma Jones, firefighter extraordinaire, tough cookie and kitten lover. Beat 10 levels of dangerous mountain terrain, improving Jones’ skills with every fluffy life saved. Dominate your friends on the kitty-saving leaderboards, and gain the adoration of millions of cats! Save the kitties! You’re their only hope!' FROM games WHERE igdb_id = 15495 ON CONFLICT (game_id, language_code) DO NOTHING;
