INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Barbarian DX', 'Tiny Barbarian DX is an action-packed sword ''em up inspired by fantasy pulp fiction. Like those short stories, the game is split into four distinct episodes, each with a new setting, new enemies, and new music! Best of all, when you buy the game, you will get all other episodes as they become available! Episode 1 is available now, with more coming soon! What are you waiting for? It''s Time to Get Tiny!' FROM games WHERE igdb_id = 16693 ON CONFLICT (game_id, language_code) DO NOTHING;
