INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oozi: Earth Adventure', 'Oozi: Earth Adventure is a classic 2D platformer with old school gameplay - no puzzles, no punishment, just 100% pure classic platforming fun! Its most prominent features are HD visuals and beautiful hand-drawn art, but despite its visual style, it’s a good fit for all kinds of gamers. The variety of difficulty levels – from Kid to Hardcore – allows everyone to enjoy the game regardless of their skill level. It tells the story of Oozi - an alien spaceship pilot who crashed on planet Earth, lost his space suit and needs to find his way home.' FROM games WHERE igdb_id = 16738 ON CONFLICT (game_id, language_code) DO NOTHING;
