INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skylanders: Swap Force', 'Skylanders: Swap Force is a platformer video game developed by Vicarious Visions and published by Activision. It is the third main game in the Skylanders video game and toy franchise, following 2012''s Skylanders: Giants, which was a direct sequel to 2011''s Skylanders: Spyro''s Adventure (the spin-off of The Legend of Spyro series). It is the game before Skylanders: Trap Team and features the voices of John DiMaggio, Jess Harnell, Audrey Wasilewski, Richard Tatum, David Sobolov, Josh Keaton, Keythe Farley, Dave Wittenberg, Joey Camen, Gregg Berger, Troy Baker and Robin Atkin Downes.
