INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo: Spartan Assault', 'Enlist as a Spartan soldier and sharpen your tactical skills in battle! Set between the events of Halo 3 and Halo 4, Halo: Spartan Assault, developed by 343 Industries in conjunction with Vanguard Games, is a new chapter within the award-winning Halo universe. Spanning over 30 missions in vibrant, dangerous worlds, dive deeper into the backstory of Human-Covenant wars and the origins of the Spartan Ops program.' FROM games WHERE igdb_id = 4839 ON CONFLICT (game_id, language_code) DO NOTHING;
